 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Uniform full rows/columns are the grid separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    separator = grid[sep_rows[0]][0] if sep_rows else grid[0][sep_cols[0]]
    def spans(size, cuts):
        result, start = [], 0
        for cut in cuts + [size]:
            if start < cut:
                result.append((start, cut))
            start = cut + 1
        return result
    rows = spans(h, sep_rows)
    cols = spans(w, sep_cols)
    # The regular background is the most common non-separator color.
    freq = Counter(grid[r][c] for r in range(h) for c in range(w)
                   if r not in sep_rows and c not in sep_cols and grid[r][c] != separator)
    background = freq.most_common(1)[0][0]
    result = []
    for r0, r1 in rows:
        outrow = []
        for c0, c1 in cols:
            anomalies = sum(grid[r][c] != background and grid[r][c] != separator
                            for r in range(r0, r1) for c in range(c0, c1))
            outrow.append(1 if anomalies >= 2 else background)
        result.append(outrow)
    return result
